// Template DOCX DÍVIDA EM ATRASO — embutido em base64.
// Usado por gerarPecaFinal() em src/docx.js via window.TEMPLATE_DOCX_BASE64_DIVIDA_ATRASO.
// Gerado a partir de "PETIÇÃO INICIAL - DÍVIDA EM ATRASO.docx" com placeholders
// dinâmicos cliente_*, caso_*, selfie image, ZZTABELADESCONTOSZZ marker, e
// 8 placeholders de IA injetados em âncoras textuais.
//
// A peça original narrava um empréstimo creditado e sacado no mesmo dia dos
// débitos. Esse trecho saiu do template: pouco peso argumentativo e muita
// margem pra erro de preenchimento. O que a peça afirma agora vem todo da
// planilha do Finder — quantidade de lançamentos, janela de datas, menor e
// maior valor, código de operação.
// 2026-09-09: o styles.xml não definia fonte no rPrDefault (os outros templates
// trazem Cambria 12 ali). Metade dos runs herda dali; sem isso o Word os punha
// em Times New Roman 10 e a peça saía com duas fontes. Corrigido no próprio
// template; docx.js também garante isso na geração (garantirFontePadrao).
const TEMPLATE_DOCX_BASE64_DIVIDA_ATRASO =
'';
